class Observation:
    def __init__(self, count):
        self.count = count
    @property
    def count(self):
        return self._count
    @count.setter
    def count(self, value):
        if value < 0:
            raise ValueError("수량은 0 이상이어야 합니다")
        self._count = value

record = Observation(4)
record.count = 5
print(record.count)
